def f(inp):
    i=np.array(inp); H,W=i.shape; out=np.zeros((H,W),int)
    # rays continue past edges: left ray goes down-left until col -1 then wraps to right side? pair1 shows left leg continuing as 1s going down-RIGHT starting one below corner. Right leg continues as 1s going down-LEFT!
    # So each leg, after reaching an edge, flips direction horizontally and continues with 1s. Left leg: down-LEFT hits col0, next step becomes down-RIGHT with 1s. Right leg: down-RIGHT hits last col, next step down-LEFT with 1s.
    for r,c in zip(*np.where(i==2)):
        # left leg
        rr,cc=r,c; d=2; 
        while True:
            out[rr,cc]=d
            cc-=1; rr+=1
            if not(0<=cc<W):
                d=1; cc+=1  # bounce
            if rr>=H: break
        # right leg
        rr,cc=r,c
        while True:
            out[rr,cc]=d
            cc+=1; rr+=1
            if cc>=W:
                d=1; cc-=1
            if rr>=H: break
    return out.tolist()
